import sys
from collections import deque, defaultdict

def parse_paper(line):
    if ':' not in line:
        return None
    colon_pos = line.index(':')
    authors_part = line[:colon_pos]
    authors = [a.strip() for a in authors_part.split(',')]
    return authors

def main():
    data = sys.stdin.read().splitlines()
    idx = 0
    num_scenarios = int(data[idx].strip())
    idx = 1

    for scenario in range(1, num_scenarios + 1):
        parts = data[idx].split()
        P = int(parts[0])
        N = int(parts[1])
        idx += 1

        papers = []
        for _ in range(P):
            line = data[idx].strip()
            idx += 1
            authors = parse_paper(line)
            if authors:
                papers.append(authors)

        names = []
        for _ in range(N):
            name = data[idx].strip()
            names.append(name)
            idx += 1

        graph = defaultdict(set)
        all_authors = set()

        for authors in papers:
            for author in authors:
                all_authors.add(author)

        for authors in papers:
            for i in range(len(authors)):
                for j in range(i + 1, len(authors)):
                    graph[authors[i]].add(authors[j])
                    graph[authors[j]].add(authors[i])

        erdos = "Erdos, P."
        if erdos not in all_authors:
            result = {}
            for name in names:
                result[name] = "infinity"
        else:
            distances = {erdos: 0}
            queue = deque([erdos])

            while queue:
                current = queue.popleft()
                for neighbor in graph[current]:
                    if neighbor not in distances:
                        distances[neighbor] = distances[current] + 1
                        queue.append(neighbor)

            result = {}
            for name in names:
                if name in distances:
                    result[name] = distances[name]
                else:
                    result[name] = "infinity"

        print(f"Scenario {scenario}")
        for name in names:
            print(f"{name} {result[name]}")

if __name__ == "__main__":
    main()
